    for (int c = 1; c <= w->cols; c++) {
        w->grid[0 * stride + c] = w->grid[w->rows * stride + c];           // Letzte echte Zeile -> Rahmen Oben
        w->grid[(w->rows + 1) * stride + c] = w->grid[1 * stride + c];     // Erste echte Zeile -> Rahmen Unten
