            else if (current_gen->grid[i - 1] == TEAM_BLUE) blue_neighbors++;
            if (current_gen->grid[i + 1] == TEAM_RED) red_neighbors++;
            else if (current_gen->grid[i + 1] == TEAM_BLUE) blue_neighbors++;

